package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.lang.reflect.WildcardType;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.internal.util.Checks;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMetadataSupport_registerTypeVariablesOn_TriageGen0Test {

    private GenericMetadataSupportTestable target;

    /**
     * Subclass to expose the protected method and access the protected field 
     * contextualActualTypeParameters for verification.
     */
    private static class GenericMetadataSupportTestable extends GenericMetadataSupport {
        @Override
        public Class<?> rawType() {
            return null;
        }

        @Override
        public java.util.List<Type> extraInterfaces() {
            return null;
        }

        @Override
        public Class<?>[] rawExtraInterfaces() {
            return null;
        }

        @Override
        public boolean hasRawExtraInterfaces() {
            return false;
        }

        @Override
        public Map<TypeVariable, Type> actualTypeArguments() {
            return null;
        }

        @Override
        public GenericMetadataSupport resolveGenericReturnType(java.lang.reflect.Method method) {
            return null;
        }

        // This is a helper to invoke the protected method
        void callRegisterTypeVariablesOn(Type type) {
            registerTypeVariablesOn(type);
        }

        // Accessor for testing purposes
        Map<TypeVariable, Type> getContextualActualTypeParameters() {
            return contextualActualTypeParameters;
        }

        // Mocking the boundsOf method which is likely internal/protected
        // Since we don't have the implementation of boundsOf, we assume it's part of the class
        // and we will mock the behavior if needed, but here we rely on the real logic if possible.
        // However, since we can't override it easily without knowing its signature, 
        // we will assume it returns the type or handles WildcardType.
        @Override
        protected Type boundsOf(WildcardType wildcardType) {
            // For the sake of testing the branch, we return the wildcard itself 
            // or a dummy type to verify the path was taken.
            return wildcardType;
        }
    }

    @Before
    public void setUp() {
        target = new GenericMetadataSupportTestable();
    }

    @Test
    public void testRegisterTypeVariablesOn_NotParameterizedType() {
        Type nonParameterizedType = String.class;
        target.callRegisterTypeVariablesOn(nonParameterizedType);
        assertEquals(0, target.getContextualActualTypeParameters().size());
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testRegisterTypeVariablesOn_WithActualTypeArguments() throws Exception {
        // Setup: List<String>
        ParameterizedType parameterizedType = mock(ParameterizedType.class);
        Class<List> rawType = List.class;
        TypeVariable<List<String>> typeVariable = mock(TypeVariable.class);
        Type actualType = String.class;

        when(parameterizedType.getRawType()).thenReturn(rawType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{actualType});
        when(rawType.getTypeParameters()).thenReturn(new TypeVariable[]{typeVariable});

        target.callRegisterTypeVariablesOn(parameterizedType);

        Map<TypeVariable, Type> result = target.getContextualActualTypeParameters();
        assertEquals(1, result.size());
        assertEquals(actualType, result.get(typeVariable));
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testRegisterTypeVariablesOn_WithWildcardType() throws Exception {
        // Setup: List<? extends Number>
        ParameterizedType parameterizedType = mock(ParameterizedType.class);
        Class<List> rawType = List.class;
        TypeVariable<List<?>> typeVariable = mock(TypeVariable.class);
        WildcardType wildcardType = mock(WildcardType.class);

        when(parameterizedType.getRawType()).thenReturn(rawType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{wildcardType});
        when(rawType.getTypeParameters()).thenReturn(new TypeVariable[]{typeVariable});

        target.callRegisterTypeVariablesOn(parameterizedType);

        Map<TypeVariable, Type> result = target.getContextualActualTypeParameters();
        assertEquals(1, result.size());
        // Based on our override of boundsOf in the testable class, it should return the wildcardType
        assertEquals(wildcardType, result.get(typeVariable));
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testRegisterTypeVariablesOn_MultipleArguments() throws Exception {
        // Setup: Map<String, ? extends Integer>
        ParameterizedType parameterizedType = mock(ParameterizedType.class);
        Class<Map> rawType = Map.class;
        TypeVariable<Map<String, ?>> tv1 = mock(TypeVariable.class);
        TypeVariable<Map<String, ?>> tv2 = mock(TypeVariable.class);
        Type arg1 = String.class;
        WildcardType arg2 = mock(WildcardType.class);

        when(parameterizedType.getRawType()).thenReturn(rawType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{arg1, arg2});
        when(rawType.getTypeParameters()).thenReturn(new TypeVariable[]{tv1, tv2});

        target.callRegisterTypeVariablesOn(parameterizedType);

        Map<TypeVariable, Type> result = target.getContextualActualTypeParameters();
        assertEquals(2, result.size());
        assertEquals(arg1, result.get(tv1));
        assertEquals(arg2, result.get(tv2));
    }
}
